//     grid1.setRef({ref:"response/vector2_grid", baseNode:"vector2_grid", dataScope:""}); 
// };



scwin.btn_getRowCount_onclick = function (e) {
	let rtn = target1.getWindow().grid1.getRowCount();

    wf_body_bottom.getObj("scwin").setReturnValue("getRowCount : " + rtn);    
};
